function card(i){registry.set(i.id,i);let id=esc(i.id),star=fav.some(x=>x.id===i.id);return '<article class="card"><div class="cover '+esc(i.kind)+'">'+(i.image?'<img loading="lazy" src="'+safe(i.image)+'" alt="" onerror="this.style.display=\'none\'">':i.kind==='audio'?'♫':i.kind==='podcast'?'◉':'▤')+'</div><div class="details"><small>'+esc(i.author)+(i.year?' · '+esc(i.year):'')+'</small><h3>'+esc(i.title)+'</h3>'+(i.desc?'<p>'+esc(i.desc.slice(0,145))+'</p>':'')+'<div class="actions">'+(i.url?'<button data-act="play" data-id="'+id+'">▶ Écouter</button>':'')+(i.read?'<button data-act="read" data-id="'+id+'">Lire</button>':'')+(i.download?'<a target="_blank" rel="noopener" href="'+safe(i.download)+'">↓ Télécharger</a>':'')+(i.source?'<a target="_blank" rel="noopener" href="'+safe(i.source)+'">Source ↗</a>':'')+'<button aria-label="Favori" data-act="fav" data-id="'+id+'">'+(star?'♥':'♡')+'</button><button aria-label="Partager" data-act="share" data-id="'+id+'">↗</button></div></div></article>'}
