async function read(i){$('reader').hidden=false;$('rtitle').textContent=i.title;$('rtext').textContent='Chargement du texte…';try{const r=await fetch('/api/read?id='+encodeURIComponent(i.read));if(!r.ok)throw Error();$('rtext').textContent=(await r.json()).text}catch{$('rtext').textContent='Texte indisponible. Vous pouvez ouvrir la source officielle depuis la fiche.'}}
let recorder=null;
function studio(){let chunks=[];$('record').onclick=async()=>{try{let s=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];recorder=new MediaRecorder(s);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{let url=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));let a=document.createElement('audio');a.controls=true;a.src=url;let l=document.createElement('a');l.href=url;l.download=($('podtitle')?.value||'podcast')+'.'+(recorder.mimeType.includes('mp4')?'m4a':recorder.mimeType.includes('ogg')?'ogg':'webm');l.textContent='Télécharger mon enregistrement';l.className='gold';if($('recresult'))$('recresult').replaceChildren(a,l);s.getTracks().forEach(t=>t.stop());if($('record')){$('record').disabled=false;$('stop').disabled=true}};recorder.start();$('record').disabled=true;$('stop').disabled=false;$('studioStatus').textContent='Enregistrement en cours.'}catch{$('studioStatus').textContent='Autorisez le microphone pour enregistrer.'}};$('stop').onclick=()=>{if(recorder?.state==='recording')recorder.stop();$('studioStatus').textContent='Enregistrement terminé.'};$('localfile').onchange=async e=>{let f=e.target.files[0];if(!f)return;if(f.name.endsWith('.txt'))$('script').value=await f.text();else if(f.type==='application/pdf')window.open(URL.createObjectURL(f),'_blank');else play({title:f.name,url:URL.createObjectURL(f)})};$('speak').onclick=()=>{let t=$('script').value.trim();if(!t){$('studioStatus').textContent='Ajoutez un texte à lire.';return}let u=new SpeechSynthesisUtterance(t);u.lang='fr-FR';speechSynthesis.cancel();speechSynthesis.speak(u)};$('silence').onclick=()=>speechSynthesis.cancel()}
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.tab){if(recorder?.state==='recording')recorder.stop();go(d.tab)}if(d.feed){feed=d.feed;render();load()}if(d.genre){genre=d.genre;document.querySelectorAll('[data-genre]').forEach(x=>x.classList.toggle('active',x.dataset.genre===genre));load()}if(d.page){page=Math.max(1,page+Number(d.page));load()}if(d.act){let i=registry.get(d.id);if(!i)return;if(d.act==='play')play(i);if(d.act==='read')read(i);if(d.act==='fav'){fav=fav.some(x=>x.id===i.id)?fav.filter(x=>x.id!==i.id):[...fav,i];localStorage.setItem('op-fav',JSON.stringify(fav));if(tab==='Favoris')render();else document.querySelectorAll('[data-act="fav"]').forEach(x=>{if(x.dataset.id===i.id)x.textContent=fav.some(f=>f.id===i.id)?'♥':'♡'})}if(d.act==='share'){try{if(navigator.share)await navigator.share({title:i.title,url:i.source||i.url});else{await navigator.clipboard.writeText(i.source||i.url);b.textContent='Copié'}}catch{}}}});
$('search').onsubmit=e=>{e.preventDefault();query=$('q').value;if(!['Podcasts','Livres audio','À lire'].includes(tab)){tab='À lire';render()}page=1;load()};
$('closePlayer').onclick=()=>{$('audio').pause();$('player').hidden=true};$('rate').onchange=()=>{$('audio').playbackRate=Number($('rate').value)};$('audio').onerror=()=>{$('audioerror').textContent='Lecture indisponible. Consultez la source officielle.'};$('closeReader').onclick=()=>{$('reader').hidden=true};$('smaller').onclick=()=>{$('rtext').style.fontSize=(size=Math.max(14,size-2))+'px'};$('bigger').onclick=()=>{$('rtext').style.fontSize=(size=Math.min(32,size+2))+'px'};$('night').onclick=()=>$('reader').classList.toggle('night');render();


