let queue=[],part=0,book=null,request=0,restoring=false;
const el=$('audio'),bar=$('chapterbar'),chooser=$('chapters');
function saved(i){try{return JSON.parse(localStorage.getItem('op-progress:'+i.id)||'null')}catch{return null}}
function persist(){if(book&&el.currentSrc&&Number.isFinite(el.currentTime)&&!restoring){try{localStorage.setItem('op-progress:'+book.id,JSON.stringify({part,time:el.currentTime}))}catch{}}}
function session(){
 if(!('mediaSession'in navigator)||!book)return;
 try{navigator.mediaSession.metadata=new MediaMetadata({title:book.title,artist:book.author||'Ondes & Pages',album:queue.length>1?queue[part].title:'Ondes & Pages',artwork:[{src:new URL('/icon.svg',location.href).href,type:'image/svg+xml',sizes:'192x192'}]});navigator.mediaSession.playbackState=el.paused?'paused':'playing'}catch{}
}
function setPosition(){if('mediaSession'in navigator&&Number.isFinite(el.duration)&&el.duration>0){try{navigator.mediaSession.setPositionState({duration:el.duration,position:Math.min(el.currentTime,el.duration),playbackRate:el.playbackRate})}catch{}}}
function chapter(index,time=0,autoplay=true){
 if(index<0||index>=queue.length)return;
 part=index;restoring=true;chooser.value=String(index);$('prevchapter').disabled=index===0;$('nextchapter').disabled=index===queue.length-1;
 const p=queue[index];$('track').textContent=book.title;
 if(queue.length>1){const small=document.createElement('small');small.textContent=(index+1)+' / '+queue.length+' · '+p.title;$('track').append(small)}
 $('audioerror').textContent='';el.src=p.url;el.playbackRate=Number($('rate').value)||1;
 const src=p.url;el.addEventListener('loadedmetadata',()=>{if(queue[part]?.url!==src)return;if(time>0&&time<el.duration)el.currentTime=time;restoring=false;setPosition()},{once:true});
 session();if(autoplay)el.play().catch(()=>{$('audioerror').textContent='Appuie sur ▶ pour reprendre la lecture.'});
}
function setupQueue(i,tracks){book=i;selected=i;queue=tracks;part=0;$('player').hidden=false;bar.hidden=tracks.length<=1;bar.style.display=tracks.length<=1?'none':'flex';chooser.replaceChildren(...tracks.map((t,j)=>new Option((j+1)+' · '+t.title,String(j))));let s=saved(i);chapter(Math.min(tracks.length-1,s?.part||0),s?.time||0)}
const oldPlay=play;
play=async function(i){
 const token=++request;persist();
 if(i.id==='lv-tour'&&!i.bookId)i=tour;
 const bid=i.bookId||(i.kind==='audio'&&/^lv\d+$/.test(i.id)?i.id.slice(2):null);
 if(!bid){if(!i.url)return;setupQueue(i,[{title:i.title,url:i.url}]);return}
 $('player').hidden=false;$('track').textContent=i.title;$('audioerror').textContent='Chargement des chapitres…';el.pause();
 try{const r=await fetch('/api/chapters?id='+encodeURIComponent(bid));if(!r.ok)throw Error();const d=await r.json();if(token!==request)return;if(!d.tracks?.length)throw Error();setupQueue(i,d.tracks)}
 catch{if(token!==request)return;if(i.url){setupQueue(i,[{title:'Édition intégrale',url:i.url}]);$('audioerror').textContent='Liste des chapitres indisponible : lecture du fichier intégral.'}else{$('audioerror').textContent='Chapitres indisponibles. Consulte la source officielle.'}}
};
const oldCard=card;
card=function(i){
 if(i.id==='lv-tour')i=tour;
 if(i.bookId||(i.kind==='audio'&&/^lv\d+$/.test(i.id))){
  const x={...i,url:i.url||'https://librivox.org/rss/'+(i.bookId||i.id.slice(2))};
  return oldCard(x).replace('▶ Écouter','▶ Écouter le livre');
 }
 return oldCard(i);
};
const oldRender=render;
render=function(){oldRender();if(tab==='Podcasts'&&publisherLinks[feed]){
 const a=document.createElement('a');a.href=publisherLinks[feed];a.target='_blank';a.rel='noopener';a.textContent='Site officiel de l’émission ↗';a.className='hint';$('content').append(a)
}};
chooser.onchange=()=>{persist();chapter(Number(chooser.value))};$('prevchapter').onclick=()=>{persist();chapter(part-1)};$('nextchapter').onclick=()=>{persist();chapter(part+1)};
el.addEventListener('ended',()=>{if(part+1<queue.length)chapter(part+1);else persist()});
el.addEventListener('timeupdate',()=>{persist();setPosition()});el.addEventListener('play',session);el.addEventListener('pause',()=>{persist();session()});el.addEventListener('ratechange',setPosition);
document.addEventListener('visibilitychange',()=>{persist();session()});window.addEventListener('pagehide',persist);
$('closePlayer').onclick=()=>{request++;persist();el.pause();$('player').hidden=true};
if('mediaSession'in navigator){
 const handlers={play:()=>el.play().catch(()=>{}),pause:()=>el.pause(),seekbackward:d=>{el.currentTime=Math.max(0,el.currentTime-(d.seekOffset||15))},seekforward:d=>{el.currentTime=Math.min(el.duration||Infinity,el.currentTime+(d.seekOffset||30))},seekto:d=>{if(Number.isFinite(d.seekTime))el.currentTime=d.seekTime},previoustrack:()=>chapter(part-1),nexttrack:()=>chapter(part+1),stop:()=>el.pause()};
 for(const [k,fn]of Object.entries(handlers)){try{navigator.mediaSession.setActionHandler(k,fn)}catch{}}
}
render();

