let mediaFilter='Tous',themeFilter='Tous',topicFilter='Tous',readingGenre='Tous',episodePage=1,episodeSort='recent',episodeYear='',episodeTerm='',currentEpisodes=[],catalogRequest=0;
const previousRender=render,previousLoad=load,previousCard=card,previousRead=read;
function fmtOptions(values,selected){return ['Tous',...values].map(v=>'<option '+(v===selected?'selected':'')+'>'+esc(v)+'</option>').join('')}
function availableShows(){return showList.filter(s=>(mediaFilter==='Tous'||mediaFilter===s.media)&&(themeFilter==='Tous'||themeFilter===s.theme)&&(topicFilter==='Tous'||topicFilter===s.topic))}
function renderShows(){
 let list=availableShows();
 $('showgrid').innerHTML=list.length?list.map(s=>'<button class="show-tile '+(s.id===feed?'active':'')+'" data-show="'+s.id+'"><strong>'+esc(s.name)+'</strong><small>'+esc(s.media+' · '+s.topic)+'</small></button>').join(''):'<p class="hint">Aucune émission dans cette sélection.</p>';
}
function displayEpisodes(){
 if(!$('episodes'))return;
 let a=currentEpisodes.filter(i=>(!episodeYear||(i.year||'').includes(episodeYear)||String(i.title).includes(episodeYear))&&normalizeText(i.title+' '+i.desc).includes(normalizeText(episodeTerm+' '+query).trim()));
 if(episodeSort==='old')a.sort((x,y)=>String(x.date).localeCompare(String(y.date)));
 else a.sort((x,y)=>String(y.date).localeCompare(String(x.date)));
 const total=a.length;episodePage=Math.min(episodePage,Math.max(1,Math.ceil(total/30)));
 $('episodes').innerHTML=total?grid(a.slice((episodePage-1)*30,episodePage*30)):'<p class="hint">Aucun épisode correspondant dans le flux disponible.</p>';
 $('epcount').textContent=total+' épisode(s) correspondant(s) · '+currentEpisodes.length+' dans le flux';
 $('eppages').innerHTML='<button data-ep-page="-1" '+(episodePage===1?'disabled':'')+'>Précédent</button> Page '+episodePage+' / '+Math.max(1,Math.ceil(total/30))+' <button data-ep-page="1" '+(episodePage*30>=total?'disabled':'')+'>Suivant</button>';
}
async function loadEpisodes(){
 const s=showList.find(x=>x.id===feed);const token=++catalogRequest;currentEpisodes=[];episodePage=1;
 $('epcount').textContent='Chargement du flux…';$('episodes').innerHTML='';$('eppages').innerHTML='';
 if(!s||!availableShows().includes(s)){ $('epcount').textContent='Choisis une émission.';return}
 $('showtitle').textContent=s.name+' · '+s.media;
 try{let r=await fetch('/api/episodes?show='+encodeURIComponent(feed));if(!r.ok)throw Error();let d=await r.json();if(token!==catalogRequest||tab!=='Podcasts')return;currentEpisodes=d.items||[];displayEpisodes()}catch{if(token!==catalogRequest||tab!=='Podcasts')return;$('epcount').textContent='Le flux de cette émission est indisponible. Aucun épisode fictif n’est affiché.'}
}
function podcasts(){
 navigation();$('content').innerHTML='<div class="eyebrow">EXPLORER</div><h1>Podcasts</h1><section class="catalog-hero"><div class="integral-label">LE KIOSQUE AUDIO</div><h2>Les émissions, à votre façon.</h2><p>Choisis un thème, un média puis une émission. Écoute les épisodes de leurs flux publics, ou récupère le fichier d’origine si le média l’autorise.</p></section><div class="filter-grid"><label>Thème<select id="themeFilter">'+fmtOptions([...new Set(showList.map(x=>x.theme))],themeFilter)+'</select></label><label>Média<select id="mediaFilter">'+fmtOptions([...new Set(showList.map(x=>x.media))],mediaFilter)+'</select></label><label>Type / discipline<select id="topicFilter">'+fmtOptions([...new Set(showList.map(x=>x.topic))],topicFilter)+'</select></label></div><div id="showgrid" class="show-grid"></div><div class="sectionhead"><h2 id="showtitle">Épisodes</h2></div><div class="filter-grid"><label>Année<input id="episodeyear" inputmode="numeric" placeholder="2010, 2014…" value="'+esc(episodeYear)+'"></label><label>Mot-clé<input id="episodeterm" placeholder="Cazarre, NBA…" value="'+esc(episodeTerm)+'"></label><label>Ordre<select id="episodesort"><option value="recent">Récents</option><option value="old">Anciens</option></select></label></div><p id="epcount" class="hint"></p><div id="episodes"></div><div id="eppages" class="chips"></div><p class="download-hint">Les archives dépendent des flux des éditeurs. Les téléchargements peuvent s’ouvrir dans le navigateur avant l’enregistrement.</p>';
 for(const [id,set]of [['themeFilter',v=>themeFilter=v],['mediaFilter',v=>mediaFilter=v],['topicFilter',v=>topicFilter=v]])$(id).onchange=e=>{set(e.target.value);let a=availableShows();if(!a.some(x=>x.id===feed))feed=a[0]?.id||'';renderShows();loadEpisodes()};
 $('episodeyear').oninput=e=>{episodeYear=e.target.value;episodePage=1;displayEpisodes()};$('episodeterm').oninput=e=>{episodeTerm=e.target.value;episodePage=1;displayEpisodes()};$('episodesort').value=episodeSort;$('episodesort').onchange=e=>{episodeSort=e.target.value;episodePage=1;displayEpisodes()};renderShows();
}
async function reading(){
 if(!$('reading-results'))return;let token=++catalogRequest;$('reading-status').textContent='Recherche des ouvrages disponibles…';
 if(readingGenre==='BD'){$('reading-results').innerHTML=grid(bdList.filter(b=>normalizeText(b.title+' '+b.author).includes(normalizeText(query))));$('reading-status').textContent='Albums numérisés en intégralité · BnF';$('reading-pages').innerHTML='';return}
 try{let r=await fetch('/api/reading?'+new URLSearchParams({q:query,page,genre:readingGenre}));if(!r.ok)throw Error();let d=await r.json();if(token!==catalogRequest||tab!=='À lire')return;$('reading-results').innerHTML=d.items.length?grid(d.items):'<p class="hint">Aucun ouvrage avec les deux formats requis sur cette page.</p>';$('reading-status').textContent=d.items.length+' livres disponibles sur cette page';$('reading-pages').innerHTML='<button data-page="-1" '+(page===1?'disabled':'')+'>Précédent</button> Page '+page+' <button data-page="1" '+(!d.next?'disabled':'')+'>Suivant</button>'}catch{if(token!==catalogRequest||tab!=='À lire')return;$('reading-status').textContent='Catalogue temporairement indisponible.'}
}
render=function(){
 if(tab==='Podcasts'){podcasts();return}
 if(tab==='À lire'){navigation();$('content').innerHTML='<div class="eyebrow">EXPLORER</div><h1>À lire</h1><section class="catalog-hero"><h2>Une bibliothèque ouverte.</h2><p>Des œuvres à lire et télécharger, avec les formats disponibles dans la source d’origine.</p></section><div class="chips">'+['Tous','Romans','Jeunesse','Histoire','Poésie','Théâtre','BD'].map(x=>'<button class="'+(readingGenre===x?'active':'')+'" data-reading-genre="'+x+'">'+x+'</button>').join('')+'</div><div id="reading-status" class="hint"></div><div id="reading-results"></div><div id="reading-pages" class="chips"></div>';return}
 previousRender();
 if(tab==='Accueil'){const sect=document.createElement('section');sect.className='archive';sect.innerHTML='<div><small class="eyebrow">BANDE DESSINÉE</small><h2>Les albums d’autrefois</h2><p>Retrouve Bécassine et les premières BD numérisées.</p></div><button data-open-bd="1">Découvrir →</button>';$('content').append(sect)}
};
load=async function(){if(tab==='Podcasts')return loadEpisodes();if(tab==='À lire')return reading();return previousLoad()};
card=function(i){
 if(i.kind==='podcast'&&i.url){
 const h=previousCard(i);return h.replace('<button aria-label="Favori"','<button class="direct-download" data-download="'+esc(i.id)+'">↓ Audio</button><button aria-label="Favori"');
 }
 if(i.readUrl){let h=previousCard(i);return h.replace('<div class="actions">','<div class="actions"><button data-read-url="'+esc(i.id)+'">Lire l’album</button>')}
 if(i.kind==='book'&&!i.read&&!i.readUrl)return '';
 return previousCard(i);
};
read=async function(i){if(i.readUrl){window.open(i.readUrl,'_blank','noopener');return}return previousRead(i)};
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.show){feed=b.dataset.show;renderShows();loadEpisodes()}
 if(b.dataset.epPage){episodePage+=Number(b.dataset.epPage);displayEpisodes()}
 if(b.dataset.readingGenre){readingGenre=b.dataset.readingGenre;page=1;render();reading()}
 if(b.dataset.openBd){go('À lire');readingGenre='BD';render();reading()}
 if(b.dataset.readUrl){const i=registry.get(b.dataset.readUrl);if(i)read(i)}
 if(b.dataset.download){const i=registry.get(b.dataset.download);if(!i||!i.url)return;const label=b.textContent;b.textContent='Ouverture…';try{const a=document.createElement('a');a.href=i.url;a.download=(i.title||'podcast').replace(/[\\/:*?"<>|]/g,'_')+'.mp3';a.target='_blank';a.rel='noopener';document.body.append(a);a.click();a.remove()}finally{b.textContent=label}}
});
$('search').onsubmit=e=>{e.preventDefault();query=$('q').value;if(!['Podcasts','Livres audio','À lire'].includes(tab)){tab='À lire';render()}page=1;if(tab==='Podcasts'){episodePage=1;displayEpisodes()}else load()};
render();if(tab==='À lire'||tab==='Podcasts')load();

;
